import{_ as n,o as i,c as t,a3 as r}from"./chunks/framework.DWzkrVA3.js";const c=JSON.parse('{"title":"Grundbegriffe","description":"","frontmatter":{},"headers":[],"relativePath":"de/general/concepts.md","filePath":"de/general/concepts.md"}'),a={name:"de/general/concepts.md"};function l(s,e,o,u,d,h){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="grundbegriffe" tabindex="-1">Grundbegriffe <a class="header-anchor" href="#grundbegriffe" aria-label="Permalink to &quot;Grundbegriffe&quot;">​</a></h1><p>Einige Ideen ziehen sich durch ganz Anthology. Wer sie kennt, findet sich im übrigen Handbuch leichter zurecht.</p><h2 id="aufnahmen-alben-und-titel" tabindex="-1">Aufnahmen, Alben und Titel <a class="header-anchor" href="#aufnahmen-alben-und-titel" aria-label="Permalink to &quot;Aufnahmen, Alben und Titel&quot;">​</a></h2><ul><li>Eine <strong>Aufnahme</strong> ist eine Darbietung eines Musikstücks – der Ton selbst.</li><li>Ein <strong>Album</strong> (Veröffentlichung) ist eine veröffentlichte Sammlung von Titeln.</li><li>Ein <strong>Titel</strong> ist eine Aufnahme im Zusammenhang eines Albums: ihre Nummer, ihre CD und vielleicht ein Titel oder Künstler, der auf diesem Album anders lautet.</li></ul><p>Dieselbe Aufnahme erscheint oft auf mehreren Alben – dem Originalalbum, einer Kompilation, einem Remaster. Anthology behält <strong>eine Originaldatei pro Aufnahme</strong>, und jedes Album verweist darauf. Spielst du einen Titel aus einer Kompilation, zeigt und liefert Anthology ihn mit den Tags und dem Cover der Kompilation.</p><h2 id="verwaltete-und-referenzierte-originale" tabindex="-1">Verwaltete und referenzierte Originale <a class="header-anchor" href="#verwaltete-und-referenzierte-originale" aria-label="Permalink to &quot;Verwaltete und referenzierte Originale&quot;">​</a></h2><ul><li><strong>Verwaltete</strong> Originale gehören Anthology: Sie liegen im Bibliotheks-Volume, und Anthology darf sie verschieben oder durch eine bessere Kopie ersetzen.</li><li><strong>Referenzierte</strong> Originale bleiben in einem Ordner, der dir gehört. Anthology liest sie und verschiebt, benennt oder löscht sie nie; ihre Tags schreibt es nur, wenn du es erlaubst.</li></ul><h2 id="tatsachliche-qualitat" tabindex="-1">Tatsächliche Qualität <a class="header-anchor" href="#tatsachliche-qualitat" aria-label="Permalink to &quot;Tatsächliche Qualität&quot;">​</a></h2><p>Die Qualität, die eine Datei angibt (zum Beispiel «FLAC, 24 Bit»), ist nicht immer die Qualität, die sie hat: Eine verlustfreie Datei kann hochgerechneten verlustbehafteten Ton enthalten. Anthology analysiert den Ton und zeigt die <strong>tatsächliche Qualität</strong> als Abzeichen. Danach richten sich die Rangfolge von Duplikaten, der Ersatz von Dateien und die Wahl der Umwandlung – und es wird nie hochgerechnet.</p><h2 id="auftrage" tabindex="-1">Aufträge <a class="header-anchor" href="#auftrage" aria-label="Permalink to &quot;Aufträge&quot;">​</a></h2><p>Lange Arbeit – Importe, Erkennung, Qualitätsanalyse, Massenänderungen, Downloads – läuft als <strong>Auftrag</strong> auf dem Server. Aufträge zeigen ihren Fortschritt live, lassen sich pausieren und laufen nach einem Neustart weiter.</p><h2 id="prufliste-und-konflikte" tabindex="-1">Prüfliste und Konflikte <a class="header-anchor" href="#prufliste-und-konflikte" aria-label="Permalink to &quot;Prüfliste und Konflikte&quot;">​</a></h2><p>Ist sich Anthology nicht sicher – zwei Aufnahmen, die gleich sein könnten, ein MusicBrainz-Vorschlag, eine bessere Kopie einer Datei –, fragt es in der <strong>Prüfliste</strong> nach. Würde eine automatische Quelle (etwa MusicBrainz) einen von Hand gesetzten Wert ändern, wird die Änderung zum <strong>Konflikt</strong>, den du übernimmst oder ablehnst.</p><h2 id="ausgaben" tabindex="-1">Ausgaben <a class="header-anchor" href="#ausgaben" aria-label="Permalink to &quot;Ausgaben&quot;">​</a></h2><p>Musik spielt auf <strong>diesem Gerät</strong> (dem Browser) oder auf einer <strong>Ausgabe</strong> wie einer Raumfeld-Zone. Auf einer Ausgabe spielt der Server die Warteschlange Titel für Titel ab, und dein Gerät wird zur Fernbedienung.</p>',15)])])}const f=n(a,[["render",l]]);export{c as __pageData,f as default};
